Object.assign(window.I18N_DICT,{"اكتب كلمة المرور بنفسك أو اتركها فارغة ليولّدها البرنامج. تظهر مرة واحدة — أرسلها له عبر واتساب أو اطبعها. عند أول دخول يُربط الحساب بجهازه فلا يعمل على جهاز آخر.":"Type the password yourself or leave it empty for the app to generate one. It is shown once — send it via WhatsApp or print it. On first login the account binds to their device and will not work on another.","كلمة المرور (اكتبها بنفسك أو اتركها فارغة للتوليد التلقائي)":"Password (type it yourself or leave empty to auto-generate)","اكتب كلمة السر هنا…":"Type the password here…","توليد":"Generate","إنشاء الحساب":"Create account","إعادة تعيين كلمة مرور":"Reset password for","اكتب كلمة المرور الجديدة بنفسك أو اتركها فارغة ليولّدها البرنامج. القديمة تتوقف فوراً ويجب إرسال الجديدة للموظف.":"Type the new password yourself or leave it empty for the app to generate one. The old one stops immediately and the new one must be sent to the employee.","كلمة المرور الجديدة":"New password","اكتبها أو اتركها فارغة…":"Type it or leave empty…","تعيين كلمة المرور":"Set password","كلمة المرور قصيرة (4 على الأقل)":"Password too short (at least 4)","كلمة المرور قصيرة":"Password too short"});
